// Run only in a fresh, disposable database: audit rows must never be deleted.
export async function verifyD1Moderation(db,factory){
 const mod=factory(db),names=['root','moderator','outsider','reporter','target','viewer','primary'];
 const tokens=Object.fromEntries(names.map((name,i)=>[name,String(i+1).repeat(64)])),checks=[];
 const one=(sql,...p)=>db.prepare(sql).bind(...p).first(),run=(sql,...p)=>db.prepare(sql).bind(...p).run();
 function check(ok,label){if(!ok)throw new Error(label);checks.push(label);}
 async function fails(fn,label){let failed=false;try{await fn();}catch{failed=true;}check(failed,label);}
 const seed=[];
 for(const name of names){
  seed.push(db.prepare('INSERT INTO auth_accounts(id,username,password_hash,recovery_key_hash) VALUES(?,?,?,?)').bind('m8u_'+name,'m8_'+name,'password','recovery-'+name));
  seed.push(db.prepare('INSERT INTO profiles(id,user_id,username) VALUES(?,?,?)').bind('m8p_'+name,'m8u_'+name,'m8_'+name));
  seed.push(db.prepare('INSERT INTO auth_sessions(id,user_id,token_hash,expires_at) VALUES(?,?,?,?)').bind('m8s_'+name,'m8u_'+name,tokens[name],new Date(Date.now()+3600000).toISOString()));
 }
 await db.batch(seed);
 await run("INSERT INTO platform_admins(user_id) VALUES('m8u_root'),('m8u_primary')");
 await run("INSERT INTO departments(id,name,slug) VALUES('m8_mod','Moderation','moderacao'),('m8_news','News','m8_news')");
 await run("INSERT INTO permissions(code,name,scope) VALUES('moderation.manage','Manage','department'),('moderation.view','View','department'),('members.manage','Members','department'),('users.manage','Users','platform')");
 await run("INSERT INTO team_roles(id,department_id,name) VALUES('m8_manager','m8_mod','Manager'),('m8_viewer','m8_mod','Viewer'),('m8_other','m8_news','Other'),('m8_new_role','m8_news','New')");
 await run("INSERT INTO team_role_permissions(role_id,permission_code) VALUES('m8_manager','moderation.manage'),('m8_manager','members.manage'),('m8_viewer','moderation.view'),('m8_other','moderation.manage'),('m8_other','users.manage')");
 await run("INSERT INTO team_memberships(id,user_id,department_id,role_id) VALUES('m8_manager_member','m8u_moderator','m8_mod','m8_manager'),('m8_viewer_member','m8u_viewer','m8_mod','m8_viewer'),('m8_other_member','m8u_outsider','m8_news','m8_other')");
 await run("INSERT INTO stories(id,author_id,title) VALUES('m8_story','m8p_target','Story')");
 check(await mod.report(tokens.target,'m8_self','story','m8_story','spam')===null,'account cannot report its own content even when profile ID differs');
 await mod.report(tokens.reporter,'m8_report','story','m8_story','spam','Report details');
 check((await one("SELECT target_user_id FROM moderation_reports WHERE id='m8_report'")).target_user_id==='m8u_target','report target resolves to account ID rather than profile ID');
 check(await mod.report(tokens.reporter,'m8_duplicate','story','m8_story','other')===null,'duplicate open report is rejected');
 check((await mod.reports(tokens.reporter)).length===0,'reporter cannot read privileged report queue');
 check((await mod.reports(tokens.outsider)).length===0,'another departments manager cannot read moderation queue');
 check((await mod.reports(tokens.viewer)).length===1,'authorized read-only moderator can view scoped queue');
 await fails(()=>mod.reviewReport(tokens.viewer,'m8_viewer_write','m8_report','resolved'),'read-only moderator cannot review report');
 await fails(()=>mod.reviewReport(tokens.outsider,'m8_other_write','m8_report','resolved'),'another departments manager cannot review report');
 await mod.reviewReport(tokens.moderator,'m8_hide','m8_report','resolved','Internal only','hide');
 check((await one("SELECT moderation_hidden_at FROM stories WHERE id='m8_story'")).moderation_hidden_at!==null,'authorized review hides reported content');
 check((await one("SELECT action FROM admin_audit_log WHERE id='m8_hide'")).action==='moderation.report.resolved','review writes immutable audit event');
 await fails(()=>mod.reviewReport(tokens.moderator,'m8_closed','m8_report','dismissed'),'closed report cannot be arbitrarily reviewed again');
 await mod.reviewReport(tokens.moderator,'m8_restore','m8_report','resolved','','restore');
 check((await one("SELECT moderation_hidden_at FROM stories WHERE id='m8_story'")).moderation_hidden_at===null,'resolved report permits authorized restoration');
 await mod.warn(tokens.moderator,'m8_warning','report','m8_report','Please respect the platform rules.');
 check((await one("SELECT target_user_id FROM moderation_warnings WHERE id='m8_warning'")).target_user_id==='m8u_target','warning derives target from report');
 await fails(()=>mod.warn(tokens.moderator,'m8_warning_duplicate','report','m8_report','Another warning for same source.'),'same report cannot produce duplicate warning');
 await mod.report(tokens.reporter,'m8_root_report','profile','m8p_primary','other');
 await fails(()=>mod.warn(tokens.moderator,'m8_warn_root','report','m8_root_report','Root account warning attempt.'),'primary administrator cannot be warned through normal moderation');
 await fails(()=>mod.setAccountStatus(tokens.outsider,'m8_elevation','m8u_target','suspended'),'department role cannot acquire platform account-control permission');
 await fails(()=>mod.setAccountStatus(tokens.root,'m8_self_suspend','m8u_root','suspended'),'administrator cannot suspend own account');
 await fails(()=>mod.setAccountStatus(tokens.root,'m8_primary_suspend','m8u_primary','suspended'),'other primary administrator is protected from suspension');
 await mod.setAccountStatus(tokens.root,'m8_suspend','m8u_target','suspended','Reviewed reason');
 check((await one("SELECT count(*) n FROM auth_sessions WHERE user_id='m8u_target'")).n===0,'suspension revokes all target sessions atomically');
 await fails(()=>mod.setAccountStatus(tokens.root,'m8_suspend','m8u_target','active'),'failed duplicate audit write aborts administrative mutation');
 check((await one("SELECT account_status FROM auth_accounts WHERE id='m8u_target'")).account_status==='suspended','audit failure cannot partially reactivate account');
 await mod.setAccountStatus(tokens.root,'m8_reactivate','m8u_target','active');
 check((await one("SELECT count(*) n FROM auth_sessions WHERE user_id='m8u_target'")).n===0,'reactivation does not restore revoked sessions');
 await mod.submitTicket(tokens.reporter,'m8_ticket','help','Need help','Detailed support request');
 check((await mod.myTickets(tokens.outsider)).length===0,'another account cannot read own-support projection');
 await fails(()=>mod.reviewTicket(tokens.viewer,'m8_view_ticket','m8_ticket','resolved'),'read-only moderator cannot respond to ticket');
 await mod.reviewTicket(tokens.moderator,'m8_ticket_review','m8_ticket','resolved','Private staff note','Public response');
 const ticket=(await mod.myTickets(tokens.reporter))[0];
 check(ticket.response==='Public response'&&!Object.hasOwn(ticket,'internal_notes'),'reporter receives response without internal staff notes');
 await fails(()=>mod.warn(tokens.moderator,'m8_untargeted_warning','support','m8_ticket','Must not warn the reporter by default.'),'untargeted support ticket cannot warn its reporter');
 const notices=(await one("SELECT count(*) n FROM user_notifications WHERE notification_type='support_response'")).n;
 await mod.reviewTicket(tokens.moderator,'m8_ticket_review2','m8_ticket','resolved','Another internal note','Public response');
 check((await one("SELECT count(*) n FROM user_notifications WHERE notification_type='support_response'")).n===notices,'unchanged support response does not create duplicate notice');
 await fails(()=>mod.assignRole(tokens.moderator,'m8_role_cross','m8u_target','m8_new_role'),'membership manager cannot appoint in another department');
 await fails(()=>mod.assignRole(tokens.root,'m8_role_self','m8u_root','m8_new_role'),'administrator cannot appoint own team role');
 await mod.assignRole(tokens.root,'m8_appointment','m8u_target','m8_new_role');
 check((await one("SELECT assigned_by FROM team_memberships WHERE id='m8_appointment'")).assigned_by==='m8u_root','role appointment records authenticated actor');
 await fails(()=>mod.removeRole(tokens.moderator,'m8_remove_self','m8_manager_member'),'non-root staff cannot change own membership');
 await mod.removeRole(tokens.root,'m8_removal','m8_appointment','Role ended');
 check((await one("SELECT status FROM team_memberships WHERE id='m8_appointment'")).status==='removed','authorized role removal preserves membership history');
 check((await mod.audit(tokens.moderator)).length===0,'department moderator cannot read platform audit');
 check((await mod.audit(tokens.root)).length>0,'platform administrator can inspect audit');
 await fails(()=>run("UPDATE admin_audit_log SET action='changed' WHERE id='m8_hide'"),'audit event cannot be rewritten');
 await fails(()=>run("DELETE FROM admin_audit_log WHERE id='m8_hide'"),'audit event cannot be deleted');
 await run("INSERT INTO chat_threads(id,initiator_id,recipient_id,status) VALUES('m8_thread','m8p_target','m8p_reporter','accepted')");
 const reported='v2:'+'A'.repeat(40),unreported='v2:'+'B'.repeat(40);
 await run("INSERT INTO chat_messages(id,thread_id,sender_id,body_cipher,cipher_version) VALUES('m8_message','m8_thread','m8p_target',?,2),('m8_unreported','m8_thread','m8p_target',?,2)",reported,unreported);
 await run("INSERT INTO chat_reports(id,reporter_id,thread_id,message_id,reason,message_snapshot) VALUES('m8_chat_report','m8p_reporter','m8_thread','m8_message','Selected evidence',json_object('id','m8_message','thread_id','m8_thread','sender_id','m8p_target','body_cipher',?,'cipher_version',2))",reported);
 await fails(()=>mod.readChatEvidence(tokens.reporter,'m8_no_evidence',['m8_chat_report']),'ordinary participant cannot access moderation evidence endpoint');
 await fails(()=>mod.readChatEvidence(tokens.outsider,'m8_wrong_evidence',['m8_chat_report']),'another department cannot access chat evidence');
 const evidence=await mod.readChatEvidence(tokens.viewer,'m8_evidence',['m8_chat_report']);
 check(evidence.length===1&&JSON.parse(evidence[0].message_snapshot).id==='m8_message','authorized moderator receives only selected reported snapshot');
 check(!JSON.stringify(evidence).includes(unreported),'evidence read does not export unrelated conversation messages');
 check((await one("SELECT admin_user_id FROM chat_audit_access WHERE id='m8_evidence'")).admin_user_id==='m8u_viewer','evidence access is audited for actual account');
 await fails(()=>mod.readChatEvidence(tokens.root,'m8_bad_selection',['m8_chat_report','m8_missing']),'missing evidence selection aborts whole audited read');
 check((await one("SELECT count(*) n FROM chat_audit_access WHERE id='m8_bad_selection'")).n===0,'failed evidence read leaves no partial audit entry');
 await fails(()=>run("DELETE FROM chat_audit_access WHERE id='m8_evidence'"),'evidence access audit cannot be erased');
 await mod.warn(tokens.moderator,'m8_chat_warning','chat','m8_chat_report','Chat report warning with a reason.');
 check((await one("SELECT target_user_id FROM moderation_warnings WHERE id='m8_chat_warning'")).target_user_id==='m8u_target','chat warning targets reported message sender');
 await run("UPDATE team_roles SET status='archived' WHERE id='m8_manager'");
 await fails(()=>mod.reviewTicket(tokens.moderator,'m8_archived','m8_ticket','resolved'),'archived staff role cannot perform new action');
 await run("UPDATE team_roles SET status='active' WHERE id='m8_manager'");await run("UPDATE departments SET status='archived' WHERE id='m8_mod'");
 check((await mod.reports(tokens.viewer)).length===0,'archived department removes scoped read permission');
 await run("UPDATE departments SET status='active' WHERE id='m8_mod'");
 await run("UPDATE auth_sessions SET expires_at='2000-01-01T00:00:00Z' WHERE user_id='m8u_root'");
 await fails(()=>mod.setAccountStatus(tokens.root,'m8_expired','m8u_target','suspended'),'expired administrator session cannot execute mutation');
 return {passed:checks.length,checks};
}
